package com.example.securevault.model

/**
 * Abstract base class representing a Note in the SecureNotes Vault.
 * Factors together common properties and behavior inherited by PublicNote and PrivateNote.
 *
 * Database IDs are auto-generated by the database engine.
 */
abstract class Note(
    open var id: Long = 0,
    open var title: String,
    open var content: String
) {
    /**
     * Indicates whether this note is private (encrypted / password protected).
     */
    abstract fun isPrivate(): Boolean

    /**
     * Returns a short limited preview of the note's content if public,
     * or null if the note is private.
     */
    abstract fun getPreview(): String?

    /**
     * Creates a copy of this note with updated title and/or content.
     */
    abstract fun copyWith(newTitle: String = this.title, newContent: String = this.content): Note

    /**
     * Updates the title and content of this note.
     */
    open fun update(newTitle: String, newContent: String) {
        this.title = newTitle
        this.content = newContent
    }

    /**
     * Converts this note to a PublicNote.
     */
    open fun toPublic(): PublicNote {
        return PublicNote(
            id = 0, // A new Note is created when changing privacy
            title = this.title,
            content = this.content
        )
    }

    /**
     * Converts this note to a PrivateNote with the provided password.
     */
    open fun toPrivate(password: String): PrivateNote {
        return PrivateNote(
            id = 0, // A new Note is created when changing privacy
            title = this.title,
            content = this.content,
            password = password
        )
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is Note) return false
        return isPrivate() == other.isPrivate() && id == other.id && title == other.title && content == other.content
    }

    override fun hashCode(): Int {
        var result = isPrivate().hashCode()
        result = 31 * result + id.hashCode()
        result = 31 * result + title.hashCode()
        result = 31 * result + content.hashCode()
        return result
    }
}

/**
 * A standard, unencrypted note.
 * Title and short preview of content are available on the dashboard.
 */
class PublicNote(
    id: Long = 0,
    title: String,
    content: String
) : Note(id, title, content) {

    override fun isPrivate(): Boolean = false

    /**
     * For PublicNote, a short, limited preview (up to 60 characters) is available.
     */
    override fun getPreview(): String {
        val previewLength = 60
        val trimmed = content.trim()
        return if (trimmed.length > previewLength) {
            trimmed.substring(0, previewLength).trimEnd() + "..."
        } else {
            trimmed
        }
    }

    override fun copyWith(newTitle: String, newContent: String): PublicNote {
        return PublicNote(
            id = this.id,
            title = newTitle,
            content = newContent
        )
    }
}

/**
 * A private, password-protected note.
 * Title is visible on the dashboard, but content preview is NOT available.
 * Requires password authentication to view or edit.
 */
class PrivateNote(
    id: Long = 0,
    title: String,
    content: String,
    var password: String
) : Note(id, title, content) {

    override fun isPrivate(): Boolean = true

    /**
     * For PrivateNote, content preview is strictly NOT available.
     */
    override fun getPreview(): String? = null

    override fun copyWith(newTitle: String, newContent: String): PrivateNote {
        return copyWith(newTitle, newContent, this.password)
    }

    fun copyWith(newTitle: String = this.title, newContent: String = this.content, newPassword: String = this.password): PrivateNote {
        return PrivateNote(
            id = this.id,
            title = newTitle,
            content = newContent,
            password = newPassword
        )
    }

    /**
     * Verifies if the candidate password matches this note's password.
     */
    fun verifyPassword(candidate: String): Boolean {
        return this.password == candidate
    }

    override fun equals(other: Any?): Boolean {
        if (!super.equals(other)) return false
        if (other !is PrivateNote) return false
        return password == other.password
    }

    override fun hashCode(): Int {
        var result = super.hashCode()
        result = 31 * result + password.hashCode()
        return result
    }
}
